  double dx = *x1 - *x0, dy = *y1 - *y0, t0 = 0, t1 = 1;
  double p[4] = {-dx, dx, -dy, dy};
  double q[4] = {*x0, (c->w - 1) - *x0, *y0, (c->h - 1) - *y0};
  for (int i = 0; i < 4; i++) {
    if (p[i] == 0) {
      if (q[i] < 0) return 0;
    } else {
      double t = q[i] / p[i];
      if (p[i] < 0) {
        if (t > t1) return 0;
        if (t > t0) t0 = t;
      } else {
        if (t < t0) return 0;
        if (t < t1) t1 = t;
      }
    }
  }
  double ax = *x0, ay = *y0;
  *x0 = ax + t0 * dx;
  *y0 = ay + t0 * dy;
  *x1 = ax + t1 * dx;
  *y1 = ay + t1 * dy;
  return 1;
}

void canvas_line(Canvas *c, int x0, int y0, int x1, int y1, uint16_t color) {
  int ix0 = x0, iy0 = y0, ix1 = x1, iy1 = y1;
  int clipped = x0 < 0 || y0 < 0 || x0 >= c->w || y0 >= c->h || x1 < 0 ||
                y1 < 0 || x1 >= c->w || y1 >= c->h;
  if (clipped) {
    double ax = x0, ay = y0, bx = x1, by = y1;
    if (!clip_line(c, &ax, &ay, &bx, &by)) return;
    ix0 = (int)floor(ax + 0.5);
    iy0 = (int)floor(ay + 0.5);
    ix1 = (int)floor(bx + 0.5);
    iy1 = (int)floor(by + 0.5);
  }
  int dx = abs(ix1 - ix0), sx = ix0 < ix1 ? 1 : -1;
  int dy = -abs(iy1 - iy0), sy = iy0 < iy1 ? 1 : -1;
  int err = dx + dy;
  for (;;) {
    canvas_point(c, ix0, iy0, color);
    if (ix0 == ix1 && iy0 == iy1) break;
    int e2 = 2 * err;
    if (e2 >= dy) {
      err += dy;
      ix0 += sx;
    }
    if (e2 <= dx) {
      err += dx;
      iy0 += sy;
    }
  }
}

